def resolve(path, cwd, links):
    if links is None:
        links = {}

    # Normalize path: split into components
    if path.startswith('/'):
        current = '/'
        components = path[1:].split('/')
    else:
        current = cwd
        components = path.split('/')

    link_count = 0
    max_links = 8

    i = 0
    while i < len(components):
        component = components[i]
        i += 1

        # Skip empty components and '.'
        if component == '' or component == '.':
            continue

        # Handle '..'
        if component == '..':
            if current != '/':
                current = current.rsplit('/', 1)[0]
                if current == '':
                    current = '/'
            continue

        # Append component to current path
        if current == '/':
            current = '/' + component
        else:
            current = current + '/' + component

        # Check if current is a symlink
        if current in links:
            link_count += 1
            if link_count > max_links:
                return None

            target = links[current]

            # Parse target into components
            if target.startswith('/'):
                current = '/'
                target_components = target[1:].split('/')
            else:
                # Target is relative to the directory containing the link
                if current != '/':
                    current = current.rsplit('/', 1)[0]
                    if current == '':
                        current = '/'
                target_components = target.split('/')

            # Insert remaining components after target components
            components = target_components + components[i:]
            i = 0

    # Remove trailing slash unless it's '/'
    if current != '/' and current.endswith('/'):
        current = current[:-1]

    return current

